const args = $input.first().json;
if (!args.equipo || !args.elemento || !args.tipo_consulta) {
  return [{ json: { status: 'ERROR', _skip: true, message_to_agent: 'Faltan parámetros. Requiero tipo_consulta (equipo_sustrato | equipo_tinta | equipo_cabezal), equipo y elemento.' } }];
}
return [{ json: args }];

// v2 — F1: filtra records vacíos antes de procesar.

const matches = $input.all().filter(m => m.json && m.json.id && m.json.Modelo);
const args = $('Execute Workflow Trigger').first().json;

if (matches.length === 0) {
  return [{ json: {
    status: 'NOT_FOUND',
    data: null,
    message_to_agent: `No encontré el equipo "${args.equipo}" en el catálogo. Si el cliente nombró un modelo concreto (ej. HR 6004 DU, BIZHUB C450i), verificá el nombre exacto. Si está preguntando por una tecnología (DTF, UV, etc.) usá consultar_tecnologia o consultar_catalogo.`,
    trace_id: $execution.id
  } }];
}

const equipo = matches[0].json;
const elementoLower = String(args.elemento).toLowerCase();

let compatible = 'depende';
let notas = '';
let fieldChecked = '';

if (args.tipo_consulta === 'equipo_sustrato') {
  const sustratos = (equipo['Sustratos compatibles'] || []).map(s => String(s).toLowerCase());
  compatible = sustratos.length > 0 && sustratos.some(s => s.includes(elementoLower) || elementoLower.includes(s));
  fieldChecked = 'Sustratos compatibles';
  notas = compatible
    ? `Sí, el equipo ${equipo.Modelo} es compatible con ${args.elemento} (según catálogo).`
    : `El equipo ${equipo.Modelo} no lista ${args.elemento} en sus sustratos compatibles del catálogo. Para confirmar oficialmente, derivá al comercial.`;
} else if (args.tipo_consulta === 'equipo_tinta') {
  fieldChecked = 'Cabezales tipo';
  notas = `Compatibilidad de tinta requiere verificación técnica. Cabezal del equipo: ${equipo['Cabezales tipo'] || 'no especificado'}. Derivá al comercial para confirmación.`;
  compatible = 'depende';
} else if (args.tipo_consulta === 'equipo_cabezal') {
  const cab = String(equipo['Cabezales tipo'] || '').toLowerCase();
  fieldChecked = 'Cabezales tipo';
  compatible = cab && cab.includes(elementoLower);
  notas = compatible
    ? `Sí, el equipo ${equipo.Modelo} usa cabezales ${equipo['Cabezales tipo']}, compatible con lo que pregunta el cliente.`
    : `El equipo ${equipo.Modelo} usa cabezales ${equipo['Cabezales tipo'] || 'no especificado'}. No matchea exactamente con "${args.elemento}". Derivá al comercial.`;
}

return [{ json: {
  status: 'RESOLVED',
  data: { compatible, notas, equipo_referencia: equipo.Modelo, field_checked: fieldChecked },
  message_to_agent: notas,
  trace_id: $execution.id
} }];
